#include "ResolvedExpressionMathML.hpp"
#include <iomanip>
#include <sstream>
#include <stdexcept>
#include "compile/CompiledModel.hpp"
namespace bng::io { namespace {
std::string esc(const std::string& x){std::string r; for(char c:x){switch(c){case '&':r+="&amp;";break;case '<':r+="&lt;";break;case '>':r+="&gt;";break;case '"':r+="&quot;";break;case '\'':r+="&apos;";break;default:r+=c;}} return r;}
std::string symbolName(const compile::SymbolRef& s,const compile::CompiledModel& m){using K=compile::SymbolKind; switch(s.kind){case K::Parameter:{auto*p=m.parameter(compile::ParameterId::fromDenseIndex(s.index));return p?p->name:"";}case K::Function:{auto*p=m.function(compile::FunctionId::fromDenseIndex(s.index));return p?p->name:"";}case K::Observable:{auto*p=m.observable(compile::ObservableId::fromDenseIndex(s.index));return p?p->name:"";}case K::Compartment:{auto*p=m.compartment(compile::CompartmentId::fromDenseIndex(s.index));return p?p->name:"";}case K::MoleculeType:{auto*p=m.moleculeType(compile::MoleculeTypeId::fromDenseIndex(s.index));return p?p->name:"";}case K::PopulationType:{auto*p=m.populationType(compile::PopulationTypeId::fromDenseIndex(s.index));return p?p->name:"";}default:return "";}}
const char* binTag(compile::BinaryOp o){using O=compile::BinaryOp; switch(o){case O::Add:return"plus";case O::Subtract:return"minus";case O::Multiply:return"times";case O::Divide:return"divide";case O::Power:return"power";case O::Less:return"lt";case O::LessEqual:return"leq";case O::Greater:return"gt";case O::GreaterEqual:return"geq";case O::Equal:return"eq";case O::NotEqual:return"neq";case O::LogicalAnd:return"and";case O::LogicalOr:return"or";default:return nullptr;}}
const char* builtTag(compile::BuiltinFunction f){using F=compile::BuiltinFunction; switch(f){case F::Abs:return"abs";case F::Acos:return"arccos";case F::Acosh:return"arccosh";case F::Asin:return"arcsin";case F::Asinh:return"arcsinh";case F::Atan:return"arctan";case F::Atanh:return"arctanh";case F::Ceil:return"ceiling";case F::Cos:return"cos";case F::Cosh:return"cosh";case F::Exp:return"exp";case F::Floor:return"floor";case F::Ln:return"ln";case F::Max:return"max";case F::Min:return"min";case F::Sin:return"sin";case F::Sinh:return"sinh";case F::Sqrt:return"root";case F::Sum:return"plus";case F::Tan:return"tan";case F::Tanh:return"tanh";default:return nullptr;}}
std::string render(const compile::ResolvedExpression&e,const compile::CompiledModel&m,const std::string&i){using K=compile::ResolvedExpressionKind;std::ostringstream o;auto child=[&](const auto&x){return render(x,m,i+"  ");};switch(e.kind){case K::Number:o<<i<<"<cn>"<<std::setprecision(17)<<e.numberValue<<"</cn>\n";return o.str();case K::ParameterRef:case K::ObservableRef:case K::FunctionRef:{if(!e.symbol)throw std::invalid_argument("resolved expression reference has no symbol");auto n=symbolName(*e.symbol,m);if(n.empty())throw std::invalid_argument("resolved expression reference points to unknown symbol");if(e.arguments.empty())o<<i<<"<ci>"<<esc(n)<<"</ci>\n";else{o<<i<<"<apply>\n"<<i<<"  <ci>"<<esc(n)<<"</ci>\n";for(auto&a:e.arguments)o<<child(a);o<<i<<"</apply>\n";}return o.str();}case K::TimeRef:o<<i<<"<csymbol encoding=\"text\" definitionURL=\"http://www.sbml.org/sbml/symbols/time\">time</csymbol>\n";return o.str();case K::LocalRef:if(e.localName.empty())throw std::invalid_argument("empty local reference");o<<i<<"<ci>"<<esc(e.localName)<<"</ci>\n";return o.str();case K::ReactantCountRef:throw std::invalid_argument("reactant_N has no standalone SBML binding");case K::Unary:{if(e.arguments.size()!=1||!e.unaryOp)throw std::invalid_argument("malformed unary expression");if(*e.unaryOp==compile::UnaryOp::Plus)return render(e.arguments[0],m,i);const char*t=*e.unaryOp==compile::UnaryOp::Negate?"minus":*e.unaryOp==compile::UnaryOp::LogicalNot?"not":nullptr;if(!t)throw std::invalid_argument("unsupported unary expression");o<<i<<"<apply>\n"<<i<<"  <"<<t<<"/>\n"<<child(e.arguments[0])<<i<<"</apply>\n";return o.str();}case K::Binary:{if(e.arguments.size()<2||!e.binaryOp)throw std::invalid_argument("malformed binary expression");auto*t=binTag(*e.binaryOp);if(!t)throw std::invalid_argument("unsupported binary expression");o<<i<<"<apply>\n"<<i<<"  <"<<t<<"/>\n";for(auto&a:e.arguments)o<<child(a);o<<i<<"</apply>\n";return o.str();}case K::BuiltinCall:{if(!e.builtin)throw std::invalid_argument("unresolved builtin");using F=compile::BuiltinFunction;if(*e.builtin==F::Pi)return i+"<pi/>\n";if(*e.builtin==F::E)return i+"<exponentiale/>\n";if(*e.builtin==F::Time)return i+"<csymbol encoding=\"text\" definitionURL=\"http://www.sbml.org/sbml/symbols/time\">time</csymbol>\n";if(*e.builtin==F::If){if(e.arguments.size()!=3)throw std::invalid_argument("if() requires 3 args");o<<i<<"<piecewise>\n"<<i<<"  <piece>\n"<<render(e.arguments[1],m,i+"    ")<<render(e.arguments[0],m,i+"    ")<<i<<"  </piece>\n"<<i<<"  <otherwise>\n"<<render(e.arguments[2],m,i+"    ")<<i<<"  </otherwise>\n"<<i<<"</piecewise>\n";return o.str();}if(*e.builtin==F::Log10||*e.builtin==F::Log2){if(e.arguments.size()!=1)throw std::invalid_argument("log requires one arg");o<<i<<"<apply>\n"<<i<<"  <log/>\n"<<i<<"  <logbase><cn>"<<(*e.builtin==F::Log10?10:2)<<"</cn></logbase>\n"<<child(e.arguments[0])<<i<<"</apply>\n";return o.str();}auto*t=builtTag(*e.builtin);if(!t)throw std::invalid_argument("builtin has no faithful generic SBML mapping: "+e.operation);o<<i<<"<apply>\n"<<i<<"  <"<<t<<"/>\n";for(auto&a:e.arguments)o<<child(a);o<<i<<"</apply>\n";return o.str();}case K::TableFunction:throw std::invalid_argument("table functions require explicit SBML lowering");case K::Unresolved:throw std::invalid_argument("unresolved expression cannot be emitted as SBML");}throw std::invalid_argument("unknown expression kind");}
} std::string resolvedExpressionToMathML(const compile::ResolvedExpression&e,const compile::CompiledModel&m,const std::string&i){return render(e,m,i);} }
